import os

from upd_config import ROOT


def load_ui() -> str:
    """同目录下若有 update_ui.html 就以它为准（改界面不用重新打包）。"""
    ext = os.path.join(ROOT, "update_ui.html")
    try:
        if os.path.isfile(ext):
            with open(ext, "r", encoding="utf-8") as f:
                return f.read()
    except OSError:
        pass
    return ADMIN_HTML


def load_site() -> str:
    """同目录下若有 site_ui.html 就以它为准（社区网站界面）。"""
    ext = os.path.join(ROOT, "site_ui.html")
    try:
        if os.path.isfile(ext):
            with open(ext, "r", encoding="utf-8") as f:
                return f.read()
    except OSError:
        pass
    return SITE_HTML


def reload_templates() -> None:
    """启动时调用：外部 html 存在时覆盖内置模板，改界面不必重新打包。"""
    global ADMIN_HTML, SITE_HTML
    ADMIN_HTML = load_ui()
    SITE_HTML = load_site()
